package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen1Test {

    private Element parentElement;
    private Element firstChild;
    private Element secondChild;
    private Element thirdChild;

    @Before
    public void setUp() {
        parentElement = new Element(Tag.valueOf("div"), "");

        // Creating children elements
        firstChild = new Element(Tag.valueOf("span"), "");
        secondChild = new Element(Tag.valueOf("p"), "");
        thirdChild = new Element(Tag.valueOf("a"), "");

        // Adding children to parent
        parentElement.appendChild(firstChild);
        parentElement.appendChild(secondChild);
        parentElement.appendChild(thirdChild);
    }

    @Test
    public void testPreviousElementSibling_WithMultipleChildren() {
        assertEquals(firstChild, secondChild.previousElementSibling());
        assertEquals(secondChild, thirdChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WithSingleChild() {
        parentElement = new Element(Tag.valueOf("div"), "");
        firstChild = new Element(Tag.valueOf("span"), "");
        parentElement.appendChild(firstChild);

        assertNull(firstChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WhenFirstElement() {
        assertNull(firstChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WhenNoChildren() {
        parentElement = new Element(Tag.valueOf("div"), "");
        assertNull(parentElement.children().get(0).previousElementSibling());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testPreviousElementSibling_WithEmptyParent() {
        parentElement = new Element(Tag.valueOf("div"), "");
        Element emptyChild = new Element(Tag.valueOf("span"), "");
        emptyChild.parent().children().add(emptyChild); // Simulating an empty parent
        emptyChild.previousElementSibling();
    }

    @Test
    public void testPreviousElementSibling_WithTextNodeSibling() {
        TextNode textNode = new TextNode("Some text");
        parentElement.appendChild(firstChild);
        parentElement.appendChild(textNode);
        parentElement.appendChild(secondChild);

        assertEquals(firstChild, secondChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WithMixedNodeTypes() {
        Element comment = new Element(Tag.valueOf("comment"), "");
        parentElement.appendChild(firstChild);
        parentElement.appendChild(comment);
        parentElement.appendChild(secondChild);
        parentElement.appendChild(thirdChild);

        assertEquals(firstChild, secondChild.previousElementSibling());
        assertEquals(secondChild, thirdChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WithSameElementSibling() {
        Element duplicateChild = new Element(Tag.valueOf("span"), "");
        parentElement.appendChild(firstChild);
        parentElement.appendChild(duplicateChild);
        parentElement.appendChild(secondChild);

        assertEquals(firstChild, duplicateChild.previousElementSibling());
    }

    @Test
    public void testPreviousElementSibling_WithMultipleSameTagSiblings() {
        Element anotherSecondChild = new Element(Tag.valueOf("p"), "");
        parentElement.appendChild(firstChild);
        parentElement.appendChild(anotherSecondChild);
        parentElement.appendChild(secondChild);
        parentElement.appendChild(thirdChild);

        assertEquals(firstChild, secondChild.previousElementSibling());
        assertEquals(anotherSecondChild, thirdChild.previousElementSibling());
    }
}
